CREATE TABLE U3MarkAudit (student_id INTEGER NOT NULL, course_code VARCHAR(10) NOT NULL, old_mark INTEGER NULL, new_mark INTEGER NULL);
CREATE FUNCTION U3LogMark() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO U3MarkAudit VALUES
    (NEW.student_id, NEW.course_code, OLD.mark, NEW.mark);
  RETURN NEW;
END;
$$;
CREATE TRIGGER u3_mark_change
AFTER UPDATE OF mark ON U3Enrolment
FOR EACH ROW WHEN (OLD.mark IS DISTINCT FROM NEW.mark)
EXECUTE FUNCTION U3LogMark();
UPDATE U3Enrolment SET mark = mark + 1
WHERE course_code = 'DB101' AND mark IS NOT NULL;
SELECT student_id, course_code, old_mark, new_mark
FROM U3MarkAudit ORDER BY student_id;

