CREATE TABLE U3MarkAudit (student_id INTEGER NOT NULL, course_code VARCHAR(10) NOT NULL, old_mark INTEGER NULL, new_mark INTEGER NULL);
GO
CREATE TRIGGER u3_mark_change ON U3Enrolment
AFTER UPDATE AS
BEGIN
  SET NOCOUNT ON;
  INSERT INTO U3MarkAudit (student_id, course_code, old_mark, new_mark)
  SELECT i.student_id, i.course_code, d.mark, i.mark
  FROM inserted i JOIN deleted d
    ON i.student_id = d.student_id AND i.course_code = d.course_code
  WHERE i.mark <> d.mark
     OR (i.mark IS NULL AND d.mark IS NOT NULL)
     OR (i.mark IS NOT NULL AND d.mark IS NULL);
END;
GO
UPDATE U3Enrolment SET mark = mark + 1
WHERE course_code = 'DB101' AND mark IS NOT NULL;
SELECT student_id, course_code, old_mark, new_mark
FROM U3MarkAudit ORDER BY student_id;
